INSERT INTO COMPANY (COM_ID, NAME, CITY) VALUES (1, 'RED', 'New York');
INSERT INTO ORDERS (ORDER_ID, COM_ID, SALES_ID, ORDER_DATE, AMOUNT) VALUES (101, 1, NULL, '2023-01-01', 100);

